-- The last day (the sheet's today then) a reminder was written for a claim; null when it was never reminded. An OPEN or
-- PENDING claim can be reminded once per sheet-today.
ALTER TABLE claim ADD COLUMN reminded_on DATE;
-- A steward's delegation of the steward role to a user for a from-date to a to-date, inclusive: while the sheet's
-- today is inside the range the user acts as a steward, and each change the user makes is recorded for the steward.
CREATE TABLE delegation (
    id           BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id     VARCHAR(100) NOT NULL REFERENCES sheet (id),
    user_name    VARCHAR(100) NOT NULL,
    delegated_by VARCHAR(100) NOT NULL,
    from_date    DATE         NOT NULL,
    to_date      DATE         NOT NULL
);
CREATE INDEX delegation_user ON delegation (sheet_id, user_name);
-- The users watching a person, each at most once. A watcher is told (a NOTIFY record) whenever a claim of the person
-- is settled, approved or re-settled; watchers are told in the order they started watching.
CREATE TABLE person_watch (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet (id),
    person_id BIGINT       NOT NULL REFERENCES person (id),
    user_name VARCHAR(100) NOT NULL
);
CREATE UNIQUE INDEX person_watch_pair ON person_watch (person_id, user_name);
CREATE INDEX person_watch_sheet ON person_watch (sheet_id, user_name);

